<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { Page } from '@vben/common-ui';
import { Alert, Button, Card, Drawer, Input, Modal, Select, Space, Switch, Table, Tag } from 'ant-design-vue';
import { api,session } from './client';
const route=useRoute();const router=useRouter();
const kind=computed(()=>route.path.slice(1));const rows=ref<any[]>([]);const total=ref(0);const page=ref(1);const search=ref('');const status=ref('');const error=ref('');const busy=ref(false);const notice=ref('');
const detail=ref<any>(null);const showUser=ref(false);const newUser=ref({username:'',display_name:'',password:'',role:'analyst'});
const currentPassword=ref('');const newPassword=ref('');
const roles=[{value:'admin',label:'管理员'},{value:'analyst',label:'分析员'},{value:'viewer',label:'浏览员'}];
const states=[{value:'',label:'全部状态'},{value:'completed',label:'已完成'},{value:'approval_required',label:'待审批'},{value:'rejected',label:'已拒绝'},{value:'failed',label:'失败'},{value:'cancelled',label:'已取消'}];
const labels:Record<string,string>={completed:'已完成',approval_required:'待审批',failed:'失败',rejected:'已拒绝',cancelled:'已取消'};
async function load(){busy.value=true;error.value='';notice.value='';rows.value=[];try{if(kind.value==='account')return;const endpoint=['history','approvals'].includes(kind.value)?`/history?page=${page.value}&search=${encodeURIComponent(search.value)}&status=${kind.value==='approvals'?'approval_required':status.value}`:`/${kind.value}?page=${page.value}`;const data=await api(endpoint);rows.value=data.items;total.value=data.total??data.items.length;}catch(e){error.value=e instanceof Error?e.message:'加载失败';}finally{busy.value=false;}}
async function run(action:()=>Promise<unknown>){busy.value=true;error.value='';try{await action();await load();notice.value='操作成功';}catch(e){error.value=e instanceof Error?e.message:'操作失败';}finally{busy.value=false;}}
function reuse(question:string){router.push({path:'/workbench',query:{question}});}
function approve(row:any){Modal.confirm({title:'确认执行查询？',content:row.question,onOk:()=>run(()=>api(`/questions/${row.id}/approve`,{method:'POST',body:JSON.stringify({sql_hash:row.sql_hash})}))});}
function cancel(row:any){Modal.confirm({title:'确认取消此查询？',onOk:()=>run(()=>api(`/questions/${row.id}/cancel`,{method:'POST'}))});}
function createUser(){run(async()=>{await api('/users',{method:'POST',body:JSON.stringify(newUser.value)});showUser.value=false;newUser.value={username:'',display_name:'',password:'',role:'analyst'};});}
function updateUser(row:any,patch:any){Modal.confirm({title:'确认修改该用户？修改后其现有登录会失效。',onOk:()=>run(()=>api(`/users/${row.id}`,{method:'PATCH',body:JSON.stringify(patch)}))});}
async function password(){await run(async()=>{await api('/auth/password',{method:'POST',body:JSON.stringify({current_password:currentPassword.value,new_password:newPassword.value})});location.assign('/login');});}
const columns=computed(()=>{if(kind.value==='favorites')return[{title:'名称',dataIndex:'title'},{title:'业务问题',dataIndex:'question'},{title:'操作',key:'actions',width:190}];if(kind.value==='users')return[{title:'账号',dataIndex:'username'},{title:'姓名',dataIndex:'display_name'},{title:'角色',key:'role'},{title:'启用',key:'active'}];if(kind.value==='audit')return[{title:'操作人',dataIndex:'actor'},{title:'操作',dataIndex:'action'},{title:'对象',dataIndex:'object'},{title:'详情',dataIndex:'detail'},{title:'时间',key:'at'}];return[{title:'业务问题',dataIndex:'question'},{title:'发起人',dataIndex:'requested_by',width:120},{title:'状态',key:'status',width:110},{title:'创建时间',key:'created_at',width:180},{title:'操作',key:'actions',width:270}];});
onMounted(load);watch(()=>route.path,()=>{page.value=1;search.value='';status.value='';detail.value=null;load();});
</script>
<template><Page :title="String(route.meta.title)" description="平台业务管理"><div class="grid gap-4">
 <Alert v-if="error" :message="error" type="error" show-icon /><Alert v-if="notice" :message="notice" type="success" show-icon />
 <Card v-if="kind==='account'" title="个人账号" :bordered="false"><p class="mb-2">账号：{{session.user?.username}}</p><p class="mb-6">角色：{{roles.find(r=>r.value===session.user?.role)?.label}}</p><form style="max-width:400px" @submit.prevent="password"><label for="old-password" class="mb-2 block">当前密码</label><Input.Password id="old-password" v-model:value="currentPassword" autocomplete="current-password" class="mb-4" /><label for="new-password" class="mb-2 block">新密码（至少12位）</label><Input.Password id="new-password" v-model:value="newPassword" autocomplete="new-password" class="mb-4" /><Button type="primary" html-type="submit" :disabled="newPassword.length<12 || !currentPassword" :loading="busy">修改密码并重新登录</Button></form></Card>
 <Card v-else :bordered="false"><div class="mb-4 flex flex-wrap justify-between gap-3"><Space v-if="['history','approvals'].includes(kind)" wrap><Input.Search v-model:value="search" placeholder="搜索业务问题" aria-label="搜索业务问题" style="width:240px" @search="page=1;load()" /><Select v-if="kind==='history'" v-model:value="status" :options="states" style="width:140px" @change="page=1;load()" /></Space><Space><Button :loading="busy" @click="load">刷新</Button><Button v-if="kind==='users'" type="primary" @click="showUser=true">新增用户</Button></Space></div>
  <Alert v-if="kind==='users'" message="管理员可管理用户和审批全部查询；分析员可查询和审批自己的 L1 查询；浏览员只读访问自己的记录和目录。" type="info" class="mb-4" />
  <Table row-key="id" :loading="busy" :columns="columns" :data-source="rows" :scroll="{x:'max-content'}" :pagination="{current:page,pageSize:20,total,showSizeChanger:false}" @change="pagination=>{page=pagination.current??1;load()}"><template #bodyCell="{column,record}">
   <template v-if="column.key==='status'"><Tag :color="record.status==='completed'?'success':record.status==='approval_required'?'warning':'default'">{{labels[record.status]??record.status}}</Tag></template>
   <template v-else-if="column.key==='created_at'">{{new Date(record.created_at).toLocaleString('zh-CN')}}</template><template v-else-if="column.key==='at'">{{new Date(record.at*1000).toLocaleString('zh-CN')}}</template>
   <template v-else-if="column.key==='role'"><Select :value="record.role" :options="roles" style="width:120px" :disabled="busy" @change="value=>updateUser(record,{role:value})" /></template><template v-else-if="column.key==='active'"><Switch :checked="Boolean(record.active)" :disabled="busy" :aria-label="`启用${record.username}`" @change="value=>updateUser(record,{active:value})" /></template>
   <template v-else-if="column.key==='actions'"><Space wrap><template v-if="kind==='favorites'"><Button size="small" @click="reuse(record.question)">载入查询</Button><Button size="small" danger @click="Modal.confirm({title:'删除此收藏？',onOk:()=>run(()=>api(`/favorites/${record.id}`,{method:'DELETE'}))})">删除</Button></template><template v-else><Button size="small" @click="detail=record">查看</Button><Button v-if="kind==='history' && session.user?.role!=='viewer'" size="small" @click="reuse(record.question)">复用</Button><Button v-if="record.result" size="small" :href="`/api/v1/questions/${record.id}/export`">导出</Button><template v-if="kind==='approvals' && session.user?.role!=='viewer'"><Button size="small" type="primary" @click="approve(record)">审批</Button><Button size="small" danger @click="cancel(record)">取消</Button></template></template></Space></template>
  </template></Table>
 </Card>
 <Drawer :open="Boolean(detail)" title="查询详情" width="min(820px, 100vw)" @close="detail=null"><template v-if="detail"><p class="mb-4">{{detail.question}}</p><p class="mb-4">{{detail.answer||detail.error||labels[detail.status]}}</p><pre class="mb-4 overflow-auto rounded bg-muted p-4 text-sm">{{detail.normalized_sql}}</pre><Table v-if="detail.result" size="small" :data-source="detail.result.rows.map((r:any,i:number)=>({...r,_key:i}))" :columns="detail.result.columns.map((key:string)=>({title:key,dataIndex:key}))" row-key="_key" :scroll="{x:'max-content'}" /></template></Drawer>
 <Modal v-model:open="showUser" title="新增用户" :confirm-loading="busy" @ok="createUser"><label for="create-username" class="mb-1 block">账号（3–40位字母、数字或 ._-）</label><Input id="create-username" v-model:value="newUser.username" class="mb-3" autocomplete="off" /><label for="create-name" class="mb-1 block">姓名</label><Input id="create-name" v-model:value="newUser.display_name" class="mb-3" /><label for="create-password" class="mb-1 block">初始密码（至少12位）</label><Input.Password id="create-password" v-model:value="newUser.password" class="mb-3" autocomplete="new-password" /><label class="mb-1 block">角色</label><Select v-model:value="newUser.role" :options="roles" style="width:100%" /></Modal>
</div></Page></template>
